from pathlib import Path
import runpy,json,re
H=runpy.run_path(str(Path(__file__).with_name('felrapporter-2026-11-09.py')))
m,st,sol,joined=[H[k] for k in ['m','st','sol','joined']]
b=H['read']('uppgifter2.js');old={q['id']:json.loads(json.dumps(q)) for q in b};d={q['id']:q for q in b}
S={}
S['6.9']=sol([st(r'Tiden ombord är egentiden: \(\tau=600\) s','<p>Pelles klocka följer med skeppet. Jordens klockor mäter ett längre tidsintervall mellan läsningens början och slut.</p>'),st(r'Tidsdilatation: \(t=\tau/\sqrt{1-v^2/c^2}\)',m(r't=600/\sqrt{1-0{,}75^2}\approx907\ \mathrm s')),st(r'Jorden mäter sträckan \(s=vt\)',m(r'\begin{aligned}s&=0{,}75\cdot2{,}998\cdot10^8\cdot907{,}115\\&\approx2{,}04\cdot10^{11}\ \mathrm m\end{aligned}')),st('I Pelles system är det jorden som rör sig bort',r'<p>Under hans 600 s ökar avståndet till jorden med \(v\tau\). Skeppet står stilla i hans eget system.</p>'+m(r's_P=0{,}75c\cdot600\approx1{,}35\cdot10^{11}\ \mathrm m'))],r'Jorden: cirka \(2{,}04\cdot10^{11}\) m. Pelle: cirka \(1{,}35\cdot10^{11}\) m.')
S['6.19']=sol([st(r'Jordens avstånd är \(L_0=4350\) km','<p>Kaptenen bestämmer avståndet till jorden med samtidiga positioner i skeppets system. Det är en längdmätning, inte avståndet i ett fotografi.</p>'),st(r'Längdkontraktion: \(L=L_0\sqrt{1-v^2/c^2}\)',m(r'\begin{aligned}L&=4350\sqrt{1-0{,}970^2}\\&\approx1058\ \mathrm{km}\end{aligned}'))],r'Cirka \(1{,}06\cdot10^3\) km enligt kaptenen.')
S['6.24']=sol([st(r'Livstiden i vila är egentiden: \(\tau=2{,}2\cdot10^{-6}\) s','<p>Vi söker sträckan i jordens system, där myonen rör sig med 0,998c.</p>'),st(r'Tidsdilatation: \(t=\gamma\tau\)',m(r'\begin{aligned}\gamma&=1/\sqrt{1-0{,}998^2}\approx15{,}82\\t&\approx15{,}82\cdot2{,}2\cdot10^{-6}\ \mathrm s\end{aligned}')),st(r'Sträckan på jorden: \(s=vt\)',m(r'\begin{aligned}s&=0{,}998\cdot2{,}998\cdot10^8\cdot t\\&\approx1{,}04\cdot10^4\ \mathrm m\end{aligned}'))],'Myonen hinner cirka 10 km i jordens system.')
S['6.30']=sol([st(r'Koppla sträcka till egentid: \(L=v\gamma\tau\)',r'<p>Laboratoriets tid är \(\gamma\tau\), där pionens livstid i vila är \(\tau=2{,}8\cdot10^{-8}\) s.</p>'),st(r'Sätt \(\beta=v/c\) och samla kända värden',m(r'\begin{aligned}\frac{\beta}{\sqrt{1-\beta^2}}&=\frac{L}{c\tau}=k\\c\tau&=8{,}3944\ \mathrm m\\k&=32/8{,}3944\\&\approx3{,}812\end{aligned}')),st('Kvadrera och välj den positiva farten',m(r'\begin{aligned}\beta^2&=k^2(1-\beta^2)\\\beta&=\frac{k}{\sqrt{1+k^2}}\approx0{,}967\end{aligned}'))],'Pionens fart var cirka 0,967c.')
a=sol([st(r'Färdtid från marken: \(t=L/v\)',m(r'\begin{aligned}t&=\frac{15000}{0{,}995\cdot2{,}998\cdot10^8}\\&\approx50{,}28\ \mathrm{\mu s}\end{aligned}')),st(r'Klassisk överlevnadsandel: \(f=2^{-t/T_{1/2}}\)',r'<p>Utan relativitet skulle 1,50 μs användas som halveringstid även från marken.</p>'+m(r'f=2^{-50{,}28/1{,}50}\approx8{,}1\cdot10^{-11}'))],r'Färdtiden är cirka 50,3 μs. Den klassiska andelen är cirka \(8{,}1\cdot10^{-11}\).')
bb=sol([st(r'Myonens egentid från markens beskrivning: \(\tau=t/\gamma\)',m(r'\begin{aligned}\gamma&=1/\sqrt{1-0{,}995^2}\approx10{,}01\\\tau&=t\sqrt{1-0{,}995^2}\approx5{,}02\ \mathrm{\mu s}\end{aligned}')),st(r'I myonens system förkortas atmosfären: \(L=L_0/\gamma\)',r'<p>Myonen står stilla medan marken rör sig mot den. Tiden tills marken når myonen blir</p>'+m(r'\tau=\frac{L_0/\gamma}{v}=\frac{L_0/v}{\gamma}=\frac t\gamma')),st(r'Samma egentid ger samma sönderfall: \(f=2^{-\tau/T_{1/2}}\)',m(r'f=2^{-5{,}02/1{,}50}\approx0{,}098'))],'Cirka 9,8 % når marken. Båda referenssystemen ger samma egentid och samma andel.')
parts={'6.51':[a,bb]}
a=sol([st(r'Lorentzfaktorn vid 0,800c: \(\gamma=1/\sqrt{1-v^2/c^2}\)',m(r'\gamma=1/\sqrt{1-0{,}800^2}=5/3')),st(r'I garaget kontraheras stången: \(L=L_0/\gamma\)',m(r'L=\frac{12{,}0}{5/3}=7{,}20\ \mathrm m')+'<p>7,20 m är mindre än garagets 8,00 m: stången ryms.</p>'),st('I stångens system kontraheras garaget',m(r'L=\frac{8{,}00}{5/3}=4{,}80\ \mathrm m')+'<p>Stången är där 12,0 m lång och ryms inte i garaget.</p>')],'Garagets system: stången är 7,20 m och ryms. Stångens system: garaget är 4,80 m och stången ryms inte.')
bb=sol([st(r'Samtidighetstransformation: \(\Delta t\prime=\gamma(\Delta t-v\Delta x/c^2)\)',r'<p>Välj positiv x-riktning som stångens rörelse. Låt skillnaden avse bortre portens stängning minus den bakres. I garaget är \(\Delta t=0\) och \(\Delta x=8{,}00\) m.</p>'),st('Sätt in portavståndet och farten',m(r'\begin{aligned}\Delta t\prime&=-\frac{(5/3)\cdot0{,}800\cdot8{,}00}{2{,}998\cdot10^8}\\&\approx-35{,}6\ \mathrm{ns}\end{aligned}')),st('Minustecknet anger vilken port som stängs först','<p>Den bortre porten stängs först i stångens system och öppnas igen innan den bakre stängs. Portarna är alltså inte stängda samtidigt där. Därför kan båda beskrivningarna stämma utan att stången krockar.</p>')],'Stängningarna skiljer cirka 35,6 ns i stångens system; den bortre porten stängs först.')
# Primen ska ligga i exponentläge i formlerna.
bb=bb.replace(r'\Delta t\prime',r"\Delta t'")
parts['6.52']=[a,bb]
a=sol([st(r'Jordens tur och retur: \(t=2L_0/v\)',m(r't=2\cdot8{,}0/0{,}80=20\ \mathrm{år}')),st(r'Resenärens egentid: \(\tau=t\sqrt{1-v^2/c^2}\)',m(r'\tau=20\sqrt{1-0{,}80^2}=12\ \mathrm{år}')),st('Lägg till startåldern 25 år',m(r'\begin{aligned}25+20&=45\\25+12&=37\end{aligned}'))],'Tvillingen på jorden är 45 år och resenären 37 år.')
bb=sol([st(r'På varje reseetapp kontraheras sträckan: \(L=L_0\sqrt{1-v^2/c^2}\)',m(r'\begin{aligned}L&=8{,}0\sqrt{1-0{,}80^2}\\&=4{,}8\ \mathrm{ljusår}\end{aligned}')),st(r'Tiden i de två skeppssystemen: \(\tau=2L/v\)',m(r'\tau=2\cdot4{,}8/0{,}80=12\ \mathrm{år}'))],'Resenären får även med kontraherade avstånd totalt 12 år.')
c=sol([st('Vändningen byter den resandes inertialsystem','<p>Den resande använder ett system på utfärden och ett annat på hemfärden. Jordtvillingen kan beskriva hela förloppet i ett och samma inertialsystem. Man kan därför inte tillämpa en enda ömsesidig tidsdilatation symmetriskt på hela resan.</p>'),st('Jämför klockorna vid återseendet','<p>Beräkningen i a visar 20 förflutna år på jorden och 12 ombord. Båda tvillingarna kan jämföra sina klockor på samma plats när de återförenas.</p>')],'Den resande byter referenssystem vid vändningen; situationen för hela resan är inte symmetrisk.')
parts['6.57']=[a,bb,c]
for id,s in S.items():d[id]['s']=s;d[id]['miniräknare']=True;d[id]['geogebra']=False
for id,ss in parts.items():
 q=d[id];figs=''.join(re.findall(r'<span class="fig"><svg[\s\S]*?</svg></span>',q['s']))
 q['s']=joined(ss)+figs
 for part,s in zip(q['spelDelar'],ss):part['s']=s
 q['miniräknare']=True;q['geogebra']=False
q=d['6.24'];q['t']=q['t'].replace('Hur långt hinner myonen innan den sönderfaller?','Hur långt hinner myonen i jordens referenssystem innan den sönderfaller?')
H['save']('uppgifter2.js',b,old)
